const cp = require('child_process');
const fs = require('fs');
function run(args) {
  const result = cp.spawnSync('git', args, { encoding: 'utf8', maxBuffer: 50 * 1024 * 1024 });
  if (result.error || result.status !== 0) throw new Error((result.stderr || '') + (result.error ? String(result.error) : ''));
  return result.stdout;
}
let bundle = run(['diff', '--no-ext-diff', '--binary', 'HEAD', '--']);
const untracked = run(['ls-files', '--others', '--exclude-standard', '-z']).split('\0').filter(Boolean);
for (const path of untracked) {
  const stat = fs.statSync(path);
  bundle += '\n\n=== UNTRACKED FILE: ' + path + ' (' + stat.size + ' bytes) ===\n';
  if (stat.size > 524288) {
    bundle += '[UNREVIEWABLE_OVERSIZE_FILE]\n';
    continue;
  }
  const data = fs.readFileSync(path);
  if (data.includes(0)) bundle += '[UNREVIEWABLE_BINARY_FILE]\n';
  else bundle += data.toString('utf8');
}
process.stdout.write(JSON.stringify(bundle));

const cp = require('child_process');
const result = cp.spawnSync('cargo', ['clippy', '--all-targets', '--all-features', '--', '-D', 'warnings'], { encoding: 'utf8', maxBuffer: 20 * 1024 * 1024 });
process.stdout.write(JSON.stringify({ success: !result.error && result.status === 0, exit_code: result.status === null ? -1 : result.status, stdout: (result.stdout || '').slice(-20000), stderr: ((result.stderr || '') + (result.error ? String(result.error) : '')).slice(-20000) }));

