const cp = require('child_process');
function run(command, args) {
  const result = cp.spawnSync(command, args, { encoding: 'utf8', maxBuffer: 20 * 1024 * 1024 });
  if (result.error || result.status !== 0) {
    process.stderr.write((result.stderr || '') + (result.error ? String(result.error) : ''));
    process.exit(result.status === null ? 1 : result.status);
  }
  return result.stdout;
}
const metadata = JSON.parse(run('cargo', ['metadata', '--no-deps', '--format-version', '1']));
const files = run('git', ['ls-files']).split('\n').filter(Boolean).filter((path) => /(^|\/)(Cargo\.toml|src\/|tests\/|skills\/)/.test(path)).slice(0, 5000);
const inventory = {
  workspace_root: metadata.workspace_root,
  workspace_members: metadata.workspace_members,
  packages: metadata.packages.map((pkg) => ({ name: pkg.name, manifest_path: pkg.manifest_path, targets: pkg.targets.map((target) => ({ name: target.name, kind: target.kind, src_path: target.src_path })) })),
  relevant_files: files
};
process.stdout.write(JSON.stringify(inventory));

const fs = require('fs');
const raw = fs.readFileSync(0, 'utf8');
let parsed;
try {
  parsed = JSON.parse(raw);
  if (typeof parsed.passed !== 'boolean' || !Array.isArray(parsed.findings)) throw new Error('invalid compliance shape');
  process.stdout.write(JSON.stringify({ passed: parsed.passed, compliance_evidence: { findings: parsed.findings } }));
} catch (error) {
  process.stdout.write(JSON.stringify({ passed: false, compliance_evidence: { findings: ['Compliance response was invalid JSON: ' + String(error)] } }));
}

const fs = require('fs');
const input = JSON.parse(fs.readFileSync(0, 'utf8'));
const checks = { fmt: input.fmt, clippy: input.clippy, tests: input.tests, live_spec_planning: input.live_spec_planning };
const failures = {};
for (const [name, status] of Object.entries(checks)) {
  if (!status || status.success !== true) failures[name] = status || { success: false, stderr: 'Missing status' };
}
if (input.compliance_passed !== true) failures.compliance = input.compliance_evidence;
process.stdout.write(JSON.stringify({ all_passed: Object.keys(failures).length === 0, evidence: { attempt: input.attempt, failures } }));

