const cp = require('child_process');
const fs = require('fs');
const draft = JSON.parse(fs.readFileSync(0, 'utf8'));
const branch = process.env.BRANCH;
function run(command, args, allowFailure) {
  const result = cp.spawnSync(command, args, { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 });
  if (!allowFailure && (result.error || result.status !== 0)) {
    process.stderr.write((result.stderr || '') + (result.error ? String(result.error) : ''));
    process.exit(result.status === null ? 1 : result.status);
  }
  return result;
}
const current = run('git', ['branch', '--show-current'], false).stdout.trim();
if (current !== branch) throw new Error('Current branch does not match requested branch');
run('git', ['push', '--set-upstream', 'origin', branch], false);
let view = run('gh', ['pr', 'view', branch, '--json', 'url', '--jq', '.url'], true);
if (view.status === 0 && view.stdout.trim()) {
  process.stdout.write(view.stdout.trim());
  process.exit(0);
}
const created = run('gh', ['pr', 'create', '--base', 'main', '--head', branch, '--title', draft.title, '--body', draft.body], false);
process.stdout.write(created.stdout.trim());
